insert into public.knowledge_articles (id, organization_id, title, section, body) values
  (md5('knowledge:Bienvenida y valores')::uuid,'00000000-0000-4000-8000-000000000001'::uuid,'Bienvenida y valores','Inicio','NegoDigi opera con claridad, responsabilidad y una sola fuente de verdad para cada dato.'),
  (md5('knowledge:Operaciones y entregas')::uuid,'00000000-0000-4000-8000-000000000001'::uuid,'Operaciones y entregas','Operaciones','Los trabajos abiertos viven en Pendientes. Al entregarse, pasan al Historial. Las correcciones se solicitan por escrito y dentro de la ventana acordada.'),
  (md5('knowledge:Edición y control de calidad')::uuid,'00000000-0000-4000-8000-000000000001'::uuid,'Edición y control de calidad','Producción','Cada entrega debe respetar branding, textos, ritmo, música, color, hooks, CTA y revisión final antes de enviarse.'),
  (md5('knowledge:Precios y pagos')::uuid,'00000000-0000-4000-8000-000000000001'::uuid,'Precios y pagos','Finanzas','Los pagos del equipo se calculan sobre lo entregado. Los precios de cliente y los costes internos se mantienen separados por permisos.')
